// Inspired by https://twitter.com/Normformart/status/1414207848339361796

let palettes = [
  ["#ffd400", "#0064b0", "#001a5b", "#ffffff"],
  ["#e20404", "#fcd202", "#ffffff", "#000000"],
  ["#218ad4", "#76df55", "#0b1435", "#ffffff"]
]

function setup() {
  createCanvas(500, 500);
  // noLoop() removed for animation
  strokeWeight(5);
  strokeCap(SQUARE);
}

function draw() {
  let s = 50;
  let n = 5;
  let u = 10;

  let colors = random(palettes);

  for (let x = 0; x < width; x += (Math.max(0.001, Math.abs(s)) || 1)) {
    for (let y = 0; y < height; y += (Math.max(0.001, Math.abs(s)) || 1)) {
      shuffle(colors, true);
      noStroke();
      fill(colors[0]);
      square(x, y, s);
      stroke(colors[1]);
      noFill();
      if (random() < 1/2) {
        line(x+s/n, y+s/n, x+(n-1)*s/n, y+(n-1)*s/n);
        beginShape();
        if (random() < 1/2) {
          vertex(x+s/n, y+s/2+u);
          vertex(x+s/n, y+s/n);
          vertex(x+s/2+u, y+s/n);
        } else {
          vertex(x+(n-1)*s/n, y+s/2-u);
          vertex(x+(n-1)*s/n, y+(n-1)*s/n);
          vertex(x+s/2-u, y+(n-1)*s/n);
        }
        endShape();
      } else {
        line(x+s/n, y+(n-1)*s/n, x+(n-1)*s/n, y+s/n);
        beginShape();
        if (random() < 1/2) {
          vertex(x+(n-1)*s/n, y+s/2+u);
          vertex(x+(n-1)*s/n, y+s/n);
          vertex(x+s/2-u, y+s/n);
        } else {
          vertex(x+s/n, y+s/2-u);
          vertex(x+s/n, y+(n-1)*s/n);
          vertex(x+s/2+u, y+(n-1)*s/n);
        }
        endShape();
      }
    }
  }
}

function keyPressed() {
	if (key == " ") {
		redraw();
	}
}
